INSERT INTO fc_meta_snapshots VALUES(28,'FC27','2026-09-19','tactic','team_setting','라인 높이','커뮤니티 50~60 · 프로 60~65',NULL,'community',NULL,'낮은 수비 깊이가 라인 위치에 더 뚜렷이 반영되도록 바뀌어 극단값은 약점이 된다','fut.gg/tactics (실제 스쿼드·프로 집계, 2026-09-19 조회)','MEDIUM-HIGH — fut.gg가 추적한 실제 스쿼드·프로 사용률(표본 집계). ⚠️ 출시 2일차라 수 주 내 바뀐다.');
INSERT INTO fc_meta_snapshots VALUES(29,'FC27','2026-09-19','setting','visual','측정 시스템 (Measurement System)','미터법(Metric)','기본(Default) = 게임 언어를 따라감 · 임페리얼(Imperial) = 피트/야드','general',2,'표시 전용 설정이라 플레이 물리에는 영향이 없다. 다만 **우리 분석 파이프라인이 전부 미터법**이다 — 선수 키 cm, SofaScore·FotMob 슛 거리 m. 임페리얼로 두면 게임이 야드로 읽어줘 실측(m)과 비교할 때 1yd=0.914m만큼(약 9%) 어긋난 채로 눈대중하게 된다. ⚠️ 재시작하면 미터법이 안 먹고 임페리얼로 보이는 버그 보고가 FC26에서 다수 있었다(임페리얼↔미터법 토글로 갱신). 매 세션 카드 화면의 키 표기(cm)로 확인할 것.','EA Forums FC26 측정 시스템 버그 스레드 13003689·12995584 · magicgameworld FC26 imperial/metric 가이드 (2026-09-19 조회)','MEDIUM — 설정 위치·효과는 일치 확인. FC27에서 버그 재발 여부는 미확인');
INSERT INTO fc_meta_snapshots VALUES(30,'FC27','2026-09-19','setting','chem_style','CB 센터백','Shadow (느린 CB) / Anchor (균형)','Sentinel(이미 빠른 CB) · Backbone(빌드업 비중 큰 CB)','community',1,'FC26에서 Shadow가 속도 +6로 하향되고 차단력이 +3로 깎여 **Anchor의 값어치가 올라갔다**. 가이드 공통 규칙은 「카드가 실제로 모자란 축을 올려라」 — 속도가 낮은 CB에만 Shadow, 이미 빠르면 Sentinel.','fifauteam FC27 chemistry styles · skycoach FC27 best styles by position · MMOPIXEL position guide (2026-09-19 조회)','MEDIUM — 커뮤니티 합의. EA 공식 권장이 아니다');
INSERT INTO fc_meta_snapshots VALUES(31,'FC27','2026-09-19','setting','chem_style','FB 풀백','Shadow / Anchor','Engine(공격 가담형) · Powerhouse(크로스·공중 경합)','community',1,'윙어 대인 방어에 회복 속도가 먼저다. 공격 가담이 큰 풀백은 Engine, 크로스가 무기면 Powerhouse. **Catalyst는 메타 기본값이 아니라 공격형 한정 선택지**다.','skycoach FC27 · MMOPIXEL (2026-09-19 조회)','MEDIUM — 커뮤니티 합의');
INSERT INTO fc_meta_snapshots VALUES(32,'FC27','2026-09-19','setting','chem_style','CDM·CM 중앙','Anchor(수비형) / Engine·Maestro(배급형)','Powerhouse(패스+태클) · Architect(피지컬+패스)','community',2,'역할이 갈린다 — 뒤를 잠그면 Anchor, 전진 배급이면 Engine·Maestro. Powerhouse는 시야·패스·스탠딩 태클을 동시에 올려 **딥라잉 플레이메이커에 잘 맞는다**.','fifauteam FC27 · playhub FC26 가이드 (2026-09-19 조회)','MEDIUM — 커뮤니티 합의');
INSERT INTO fc_meta_snapshots VALUES(33,'FC27','2026-09-19','setting','chem_style','ST 스트라이커','Finisher','Hunter(느린 공격수) · Hawk(피지컬형) · Marksman(드리블형)','community',1,'이미 빠른 공격수에게 Hunter를 붙이는 건 낭비다 — 「모자란 축을 올려라」가 FC26 이후 공통 권고. 마무리가 약하면 Finisher.','fifauteam FC27 · skycoach (2026-09-19 조회)','MEDIUM — 커뮤니티 합의');
INSERT INTO fc_meta_snapshots VALUES(34,'FC27','2026-09-19','setting','chem_style','윙어 LW/RW·LM/RM','Engine / Hunter','Catalyst(배급 겸업) · Finisher(컷인 마무리)','community',2,'침투형이면 Hunter, 연계·드리블형이면 Engine. FC27 메타 예상 사용 상위권은 Hunter·Shadow·Engine·Anchor·Finisher·Hawk다.','operationsports FC26 · skycoach FC27 (2026-09-19 조회)','MEDIUM — 커뮤니티 합의');
INSERT INTO fc_meta_snapshots VALUES(35,'FC27','2026-09-19','setting','chem_style','GK 골키퍼','Glove(핸들링·다이빙) / Cat(반응·포지셔닝)','Wall(다이빙+킥) · Shield(반사+킥)','community',2,'세이브 축을 어디에 둘지의 문제다. 발밑 배급을 쓰는 골키퍼면 킥이 붙는 Wall·Shield도 후보.','fifauteam FC27 chemistry styles (2026-09-19 조회)','MEDIUM — 커뮤니티 합의');
